import{readFile}from"node:fs/promises";import{resolveRuntimeCompilerArtifactPaths}from"#runtime/loaders/artifact-paths.js";import{modelMetadataSchema}from"#internal/model-catalog.js";import{readBundledCompiledArtifacts}from"#runtime/loaders/bundled-artifacts.js";async function loadModelMetadata(e){if(e.kind===`bundled`){let e=readBundledCompiledArtifacts()?.modelMetadata;if(e===void 0)throw Error("The bundled compiled artifacts have no model metadata. Rebuild with `eve build`.");return e}let t=resolveRuntimeCompilerArtifactPaths(e.appRoot).modelMetadataPath;try{return modelMetadataSchema.parse(JSON.parse(await readFile(t,`utf8`)))}catch(e){throw e instanceof Error&&`code`in e&&e.code===`ENOENT`?Error(`The compiled artifacts have no model metadata at "${t}". Rebuild with \`eve build\`, or restart \`eve dev\`.`,{cause:e}):e}}export{loadModelMetadata};